import React, { useState, useEffect, useMemo } from 'react';
import { MapContainer, TileLayer, CircleMarker, Circle, Popup, GeoJSON } from 'react-leaflet';
import "leaflet/dist/leaflet.css";

// Componente para cambiar la vista del mapa al seleccionar un sismo
const ChangeView = ({ coordenadas }) => {
  const map = useMap();
  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7);
    }
  }, [coordenadas, map]);
  return null;
};

const MapaMexico = ({ coordenadas, theme, placas, loadingPlacas, errorPlacas }) => {
  const [circleScale, setCircleScale] = useState(1);
  const [opacity, setOpacity] = useState(0.6);

  // Validar placas antes de renderizar
  const placasValidas = useMemo(() => {
    if (!Array.isArray(placas)) {
      console.warn("Placas no es un array:", placas);
      return [];
    }
    
    return placas.filter((placa, index) => {
      // Validar estructura GeoJSON básica
      if (!placa || typeof placa !== 'object') {
        console.warn(`Placa ${index} no es un objeto válido:`, placa);
        return false;
      }
      
      if (!placa.type || placa.type !== 'Feature') {
        console.warn(`Placa ${index} no tiene type 'Feature':`, placa);
        return false;
      }
      
      if (!placa.geometry || !placa.geometry.coordinates) {
        console.warn(`Placa ${index} no tiene geometría válida:`, placa);
        return false;
      }
      
      return true;
    });
  }, [placas]);

  // Estilos para las placas
  const placaStyle = {
    color: "#3388ff",
    weight: 2,
    opacity: 0.8,
    fillOpacity: 0.1,
    fillColor: "#3388ff"
  };

  const placaHoverStyle = {
    color: "#ff7800",
    weight: 3,
    opacity: 1,
    fillOpacity: 0.3
  };

  // Función para manejar eventos de cada placa
  const onEachFeature = (feature, layer) => {
    // Popup con información
    if (feature.properties) {
      const popupContent = `
        <div style="min-width: 200px;">
          <h3 style="margin: 0 0 10px 0; color: #333;">
            ${feature.properties.nombre || 'Placa Tectónica'}
          </h3>
          <p style="margin: 0; font-size: 14px;">
            ${feature.properties.descripcion || 'Sin descripción disponible'}
          </p>
          ${feature.properties.id ? `<p style="margin: 5px 0 0 0; font-size: 12px; color: #666;">ID: ${feature.properties.id}</p>` : ''}
        </div>
      `;
      layer.bindPopup(popupContent);
    }

    // Efectos hover
    layer.on({
      mouseover: (e) => {
        const layer = e.target;
        layer.setStyle(placaHoverStyle);
        layer.bringToFront();
      },
      mouseout: (e) => {
        const layer = e.target;
        layer.setStyle(placaStyle);
      }
    });
  };

  // Animación del círculo (tu código existente)
  useEffect(() => {
    if (!coordenadas) return;

    let scale = 1;
    let opac = 0.6;

    const interval = setInterval(() => {
      scale += 0.05;
      opac = Math.max(opac - 0.01, 0);

      setCircleScale(scale);
      setOpacity(opac);

      if (scale > 3 || opac <= 0) {
        scale = 1;
        opac = 0.6;
      }
    }, 50);

    return () => clearInterval(interval);
  }, [coordenadas]);

  // Elegir capa del mapa según el tema
  const tileLayerURL = theme === "dark"
    ? "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
    : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png";

  const tileLayerAttribution = theme === "dark"
    ? '&copy; <a href="https://carto.com/">CARTO</a>'
    : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

  return (
    <div style={{ position: 'relative', height: '100%', width: '100%' }}>
      {/* Indicador de carga */}
      {loadingPlacas && (
        <div style={{
          position: 'absolute',
          top: '10px',
          right: '10px',
          background: 'rgba(255,255,255,0.9)',
          padding: '10px',
          borderRadius: '5px',
          zIndex: 1000
        }}>
          Cargando placas tectónicas...
        </div>
      )}

      {/* Indicador de error */}
      {errorPlacas && (
        <div style={{
          position: 'absolute',
          top: '10px',
          right: '10px',
          background: 'rgba(255,0,0,0.9)',
          color: 'white',
          padding: '10px',
          borderRadius: '5px',
          zIndex: 1000,
          maxWidth: '300px'
        }}>
          Error cargando placas: {errorPlacas}
        </div>
      )}

      <MapContainer
        center={[23.6345, -102.5528]}
        zoom={5}
        style={{ height: "100%", width: "100%" }}
        maxBounds={[[-90, -180], [90, 180]]} // Límites del mundo
      >
        <TileLayer 
          url={tileLayerURL} 
          attribution={tileLayerAttribution} 
          noWrap={false}
          bounds={[[-90, -180], [90, 180]]}
        />

        {/* Renderizar placas tectónicas */}
        {placasValidas.length > 0 && placasValidas.map((feature, idx) => {
          try {
            return (
              <GeoJSON
                key={`placa-${feature.properties?.id || idx}`}
                data={feature}
                style={placaStyle}
                onEachFeature={onEachFeature}
              />
            );
          } catch (error) {
            console.error(`Error renderizando placa ${idx}:`, error, feature);
            return null;
          }
        })}

        <ChangeView coordenadas={coordenadas} />
        
        {/* Marcadores de sismos (tu código existente) */}
        {coordenadas && (
          <>
            <CircleMarker
              center={[coordenadas.lat, coordenadas.lng]}
              radius={10}
              color="red"
              fillColor="red"
              fillOpacity={0.7}
            >
              <Popup>
                <b>Ubicación del Sismo</b> <br />
                Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
              </Popup>
            </CircleMarker>
            <Circle
              center={[coordenadas.lat, coordenadas.lng]}
              radius={circleScale * 50000}
              color="red"
              fillColor="red"
              fillOpacity={opacity}
              stroke={false}
            />
          </>
        )}
      </MapContainer>
    </div>
  );
};

export default MapaMexico;
